    return s1.endswith('(') and s2.startswith(')')

def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

def match_parens(lst):
    s1, s2 = lst
    open_count_s1, close_count_s1 = count_parentheses(s1)
    open_count_s2, close_count_s2 = count_parentheses(s2)

    if open_count_s1 != close_count_s1 or open_count_s2 != close_count_s2:
        return 'No'

    if not check_concatenation(s1, s2):
        return 'No'

    concatenated_string = s1 + s2
    if is_balanced(concatenated_string):
        return 'Yes'
    else:
        return 'No'

# Test cases
print(match_parens(['()(', ')']))  # Output: Yes
print(match_parens([')', ')']))     # Output: No

